#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(ggplot2);library(ggthemes)})
r<-'2026/projection-re-weight-comparison'
labels<-c(previous='Published baseline',empirical_2020_2024='Empirical 2020-2024',original_re='Original WtAgeRE',double_cv='Doubled-BTS-CV WtAgeRE')
colors<-c('Published baseline'='#333333','Empirical 2020-2024'='#D55E00','Original WtAgeRE'='#9467BD','Doubled-BTS-CV WtAgeRE'='#0072B2')
linetypes<-c('Published baseline'='dashed','Empirical 2020-2024'='longdash','Original WtAgeRE'='dotdash','Doubled-BTS-CV WtAgeRE'='solid')
s<-read_csv(file.path(r,'age_schedules.csv'),show_col_types=FALSE) |> filter(case_id=='primary') |> select(weight_case,age,fishery_weight,spawning_weight) |> pivot_longer(c(fishery_weight,spawning_weight),names_to='panel',values_to='weight_kg') |> mutate(Case=factor(labels[weight_case],levels=labels),panel=recode(panel,fishery_weight='Catch weights',spawning_weight='SSB weights'))
p<-ggplot(s,aes(age,weight_kg,color=Case,linetype=Case))+geom_line(linewidth=.8)+geom_point(size=1.7)+facet_wrap(~panel,ncol=1)+scale_color_manual(values=colors)+scale_linetype_manual(values=linetypes)+scale_x_continuous(breaks=1:15,labels=c(as.character(1:14),'15+'))+labs(x='Age',y='Weight (kg per fish)',title='Model 26.0 projection weight schedules',subtitle='Original and doubled-CV WtAgeRE: 2027 fishery forecasts at ages 3-15+, used for catch and SSB.',caption='WtAgeRE cases retain the published baseline catch/SSB values at ages 1-2. Empirical case averages all ages over 2020-2024.\nThe original WtAgeRE control separates the CV change from differences in source fit and SSB-weight specification.')+theme_few(base_size=12)+theme(legend.position='bottom',legend.title=element_blank(),plot.caption=element_text(hjust=0,size=9))+guides(color=guide_legend(nrow=2),linetype=guide_legend(nrow=2))
ggsave('2026/assets/projection-re-comparison-weights.png',p,width=11,height=9,dpi=180)
ggsave('2026/tables/projection-re-comparison-weights.pdf',p,width=11,height=9,device=cairo_pdf)
a<-read_csv(file.path(r,'native_annual_summaries.csv'),show_col_types=FALSE) |> filter(case_id=='primary',Alt==2,metric %in% c('Catch','SSB')) |> mutate(Case=factor(labels[weight_case],levels=labels),panel=recode(metric,Catch='Catch (kt)',SSB='Female spawning biomass (kt)'))
p<-ggplot(a,aes(Year,mean,color=Case,fill=Case,linetype=Case))+geom_ribbon(aes(ymin=p05,ymax=p95),alpha=.07,color=NA,linetype=0)+geom_line(linewidth=.8)+facet_wrap(~panel,ncol=1,scales='free_y')+scale_color_manual(values=colors)+scale_fill_manual(values=colors)+scale_linetype_manual(values=linetypes)+scale_x_continuous(breaks=seq(2027,2038,1))+labs(x='Year',y=NULL,title='Model 26.0 Alternative 2: four weight-schedule comparisons',subtitle='Same fitted initial population, selectivity, and recruitment draws; catch 1,375 kt in 2027-2028, then maximum ABC.',caption='Lines: means of 1,000 spmR simulations; ribbons: 5th-95th percentiles of future recruitment variation.\nSSB changes include the weight basis and subsequent mortality/age structure. This comparison retains the assessment fit.')+theme_few(base_size=12)+theme(legend.position='bottom',legend.title=element_blank(),plot.caption=element_text(hjust=0,size=9))+guides(color=guide_legend(nrow=2),fill=guide_legend(nrow=2),linetype=guide_legend(nrow=2))
ggsave('2026/assets/projection-re-comparison-trajectories.png',p,width=11,height=9,dpi=180)
ggsave('2026/tables/projection-re-comparison-trajectories.pdf',p,width=11,height=9,device=cairo_pdf)
